Compose_Task_Acknowledgement_Link.inputs:
@concat(
  'https://taskack.page.gd/index.html',
  '?item=', string(coalesce(outputs('Get_item_Task')?['body/ID'], 0)),
  '&name=', uriComponent(
    first(
      split(
        trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' ')),
        '@'
      )
    )
  ),
  '&email=', uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' '))
  ),
  '&title=', uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/Title'], '')), '\n', ' '), '\r', ' '))
  ),
  '&ref=', uriComponent(
    concat('TASK-', string(coalesce(outputs('Get_item_Task')?['body/ID'], 0)))
  )
)

Compose_SelectedItemsArray.inputs:
@if(
  greater(length(coalesce(triggerBody()?['SelectedItems'], json('[]'))), 0),
  coalesce(triggerBody()?['SelectedItems'], json('[]')),
  if(
    empty(triggerBody()?['Selected']),
    json('[]'),
    createArray(triggerBody()?['Selected'])
  )
)

Compose_SummaryText.inputs:
@concat(
  if(
    greater(length(coalesce(triggerBody()?['SelectedItems'], json('[]'))), 0),
    'Bulk assignment completed: ',
    if(not(empty(triggerBody()?['Selected'])), 'Single assignment completed: ', 'Assignment completed: ')
  ),
  string(
    if(
      greater(length(coalesce(triggerBody()?['SelectedItems'], json('[]'))), 0),
      length(triggerBody()?['SelectedItems']),
      if(empty(triggerBody()?['Selected']), 0, 1)
    )
  ),
  ' selected, ',
  string(variables('varTasksCreated')), ' tasks created, ',
  string(variables('varDocsUpdated')), ' docs updated, ',
  string(variables('varFailed')), ' failed. Notification(s) sent: ',
  string(variables('varNotificationsSent')), '.'
)

inputs.value:
@concat(
  'https://taskack.page.gd/acknowledge.html',
  '?items=',
  if(
    greater(length(coalesce(triggerBody()?['SelectedItems'], json('[]'))), 0),
    join(
      select(coalesce(triggerBody()?['SelectedItems'], json('[]')), string(item()?['ID'])),
      ','
    ),
    string(coalesce(outputs('Get_item_Task')?['body/ID'], 0))
  ),
  '&name=',
  uriComponent(
    first(
      split(
        trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' ')),
        '@'
      )
    )
  ),
  '&email=',
  uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' '))
  ),
  '&title=',
  uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/Title'], 'Bulk Assignment')), '\n', ' '), '\r', ' '))
  ),
  '&ref=',
  uriComponent(
    if(
      greater(length(coalesce(triggerBody()?['SelectedItems'], json('[]'))), 0),
      concat('BULK-', variables('varBatchBulkId')),
      concat('TASK-', string(coalesce(outputs('Get_item_Task')?['body/ID'], 0)))
    )
  ),
  '&batch=',
  uriComponent(variables('varBatchBulkId'))
)

Compose_Hybrid_AcknowledgementLink.inputs:
@concat(
  'https://taskack.page.gd/acknowledge.html',
  '?items=',
  if(
    greater(length(coalesce(triggerBody()?['SelectedItems'], json('[]'))), 0),
    join(
      union(
        split(
          replace(
            replace(
              replace(
                replace(
                  replace(
                    string(coalesce(triggerBody()?['SelectedItems'], json('[]'))),
                    '"ID":',
                    '|'
                  ),
                  '{',''
                ),
                '}',''
              ),
              '[',''
            ),
            ']',''
          ),
          '|'
        ),
        split('', '')
      ),
      ','
    ),
    string(coalesce(outputs('Get_item_Task')?['body/ID'], 0))
  ),
  '&name=',
  uriComponent(
    first(
      split(
        trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' ')),
        '@'
      )
    )
  ),
  '&email=',
  uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' '))
  ),
  '&title=',
  uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/Title'], 'Bulk Assignment')), '\n', ' '), '\r', ' '))
  ),
  '&ref=',
  uriComponent(
    if(
      greater(length(coalesce(triggerBody()?['SelectedItems'], json('[]'))), 0),
      concat('BULK-', variables('varBatchBulkId')),
